-- DMSMGR 기본 데이터 (POC 데이터 제외, 로그인 후 화면 사용에 필요한 최소 데이터)
-- 추출: 2026-10-21 00:36 / 원본 DB DMS
-- 먼저 스키마 DDL(<날짜>_DMSMGR_schema_ddl.sql)을 같은 사용자로 실행해 테이블을 만든 뒤 실행한다.
-- 로그인: 소스에 고정된 ADMIN 계정을 쓴다(사용자 테이블은 비어 있다). ADMIN 은 메뉴 권한 검사도 하지 않는다.
-- 실행: 주석 / 설정의 한글이 깨지지 않게 NLS_LANG 을 UTF-8 로 지정한 뒤 sqlplus <사용자>/<비밀번호>@<대상 DB> @<이 파일>
--   실행하면 DEFECT_FTP 암호를 묻는다(화면에 보이지 않음). 아래 DEFINE 의 FTP 주소 / 계정 / 경로는 대상 서버에 맞게 고친다.
--   대상 테이블에 이미 행이 있으면 아무것도 넣지 않고 멈춘다. 중간에 오류가 나면 모두 되돌린다(ROLLBACK).

-- DEFECT_FTP: Defect 이미지를 받는 FTP. 화면은 MAIN_PATH + DB 이미지 경로(KLARF_IMAGE_ROOT 에서 드라이브만 뺀 경로)로 받는다.
DEFINE FTP_IP = 10.86.253.162
DEFINE FTP_PORT = 21
DEFINE FTP_ID = POC
DEFINE FTP_MAIN_PATH = '/DMS_IMAGE'
ACCEPT FTP_PASS CHAR DEFAULT ' ' PROMPT 'DEFECT_FTP password: ' HIDE

SET DEFINE OFF
SET SQLBLANKLINES ON
SET VERIFY OFF
SET FEEDBACK OFF
SPOOL base_data_run.log
WHENEVER SQLERROR EXIT FAILURE ROLLBACK

-- 0. 대상 테이블이 비어 있는지 확인
DECLARE
    n NUMBER;
BEGIN
    SELECT COUNT(*) INTO n FROM "TQC_SECURITY_GROUP";
    IF n > 0 THEN RAISE_APPLICATION_ERROR(-20001, 'STOP: TQC_SECURITY_GROUP already has ' || n || ' rows. Nothing inserted.'); END IF;
    SELECT COUNT(*) INTO n FROM "TQC_FUNCTION_LIST";
    IF n > 0 THEN RAISE_APPLICATION_ERROR(-20001, 'STOP: TQC_FUNCTION_LIST already has ' || n || ' rows. Nothing inserted.'); END IF;
    SELECT COUNT(*) INTO n FROM "TQC_GROUP_FUNCTION";
    IF n > 0 THEN RAISE_APPLICATION_ERROR(-20001, 'STOP: TQC_GROUP_FUNCTION already has ' || n || ' rows. Nothing inserted.'); END IF;
    SELECT COUNT(*) INTO n FROM "TQC_CONFIG";
    IF n > 0 THEN RAISE_APPLICATION_ERROR(-20001, 'STOP: TQC_CONFIG already has ' || n || ' rows. Nothing inserted.'); END IF;
    SELECT COUNT(*) INTO n FROM "TQC_CONFIG_USER";
    IF n > 0 THEN RAISE_APPLICATION_ERROR(-20001, 'STOP: TQC_CONFIG_USER already has ' || n || ' rows. Nothing inserted.'); END IF;
    SELECT COUNT(*) INTO n FROM "TQD_DEFECT_GROUP";
    IF n > 0 THEN RAISE_APPLICATION_ERROR(-20001, 'STOP: TQD_DEFECT_GROUP already has ' || n || ' rows. Nothing inserted.'); END IF;
    SELECT COUNT(*) INTO n FROM "TQD_DEFECT_TYPE";
    IF n > 0 THEN RAISE_APPLICATION_ERROR(-20001, 'STOP: TQD_DEFECT_TYPE already has ' || n || ' rows. Nothing inserted.'); END IF;
    SELECT COUNT(*) INTO n FROM "TQD_COLORBYSIZE";
    IF n > 0 THEN RAISE_APPLICATION_ERROR(-20001, 'STOP: TQD_COLORBYSIZE already has ' || n || ' rows. Nothing inserted.'); END IF;
END;
/

-- 1. 권한 (ADMIN 외 사용자를 만들 때 쓴다)

-- TQC_SECURITY_GROUP 4건

-- TQC_FUNCTION_LIST 58건

-- TQC_GROUP_FUNCTION 112건

-- 2. 설정

-- TQC_CONFIG 126건 (시험 범주 BJ_TEST 와 DEFECT_FTP 제외, 암호 항목은 빈 값)

SET DEFINE ON

-- TQC_CONFIG 5건 (DEFECT_FTP, 값은 위 DEFINE / ACCEPT)
SET DEFINE OFF

-- TQC_CONFIG_USER 27건 (ADMIN 만)

-- 3. Defect 기준

-- TQD_DEFECT_GROUP 1건 (Default 그룹만)

-- TQD_DEFECT_TYPE 75건 (Default 그룹 유형)

-- TQD_COLORBYSIZE 16건 (ADMIN 만)

COMMIT;
WHENEVER SQLERROR CONTINUE

-- 4. 확인 (기대값: 이 파일의 표 머리 건수, 합계 424건)
SET PAGESIZE 100 FEEDBACK ON
SELECT 'TQC_SECURITY_GROUP' T, COUNT(*) N FROM TQC_SECURITY_GROUP UNION ALL SELECT 'TQC_FUNCTION_LIST', COUNT(*) FROM TQC_FUNCTION_LIST UNION ALL SELECT 'TQC_GROUP_FUNCTION', COUNT(*) FROM TQC_GROUP_FUNCTION UNION ALL SELECT 'TQC_CONFIG', COUNT(*) FROM TQC_CONFIG UNION ALL SELECT 'TQC_CONFIG_USER', COUNT(*) FROM TQC_CONFIG_USER UNION ALL SELECT 'TQD_DEFECT_GROUP', COUNT(*) FROM TQD_DEFECT_GROUP UNION ALL SELECT 'TQD_DEFECT_TYPE', COUNT(*) FROM TQD_DEFECT_TYPE UNION ALL SELECT 'TQD_COLORBYSIZE', COUNT(*) FROM TQD_COLORBYSIZE;
SELECT NAME, CASE WHEN NAME = 'PASS' THEN '(set)' ELSE VALUE END VALUE FROM TQC_CONFIG WHERE CATEGORY = 'DEFECT_FTP' ORDER BY NAME;
SPOOL OFF
